static uint8_t from_hex(char ch) {
	if (ch >= '0' && ch <= '9') {
		return (uint8_t)(ch - '0');
	}
	if (ch >= 'A' && ch <= 'F') {
		return (uint8_t)(ch - 'A' + 10);
	}
	if (ch >= 'a' && ch <= 'f') {
		return (uint8_t)(ch - 'a' + 10);
	}
	return 0;
}

