			write_reply(response, 1);
			break;
		case 'L':
			response[0] = state.slewing ? '1' : '0';
			write_reply(response, 1);
			break;
		case 'M':
			state.slewing = false;
			write_empty_reply();
			break;
		case 'p':
			response[0] = 'W';
			write_reply(response, 1);
			break;
		case 't':
			response[0] = state.tracking_mode;
			write_reply(response, 1);
			break;
		case 'T':
